#[cfg(test)]
mod conformance {
    //! Round-trip tests harvested from the spec's `spec.md`,
    //! plus a `rejects_invalid_examples` test for any fixtures
    //! in `payload.invalid-examples.json` (validate feature).
    #[test]
    fn request_example_1() {
        const JSON: &str = "{\n  \"id\": \"urn:uuid:00000000-0000-4000-8000-000000000001\",\n  \"type\": \"https://trusttasks.org/spec/vtc/schemas/list/0.1#request\",\n  \"issuer\": \"did:example:administrator\",\n  \"recipient\": \"did:example:community\",\n  \"issuedAt\": \"2026-09-28T10:00:00Z\",\n  \"threadId\": \"urn:uuid:00000000-0000-4000-8000-0000000001ff\",\n  \"payload\": {\n    \"kind\": \"issues\",\n    \"limit\": 50\n  }\n}\n";
        let doc: crate::TrustTask<super::Payload> =
            serde_json::from_str(JSON).expect("deserialize request example");
        let rendered = serde_json::to_value(&doc).expect("re-serialize");
        let expected: serde_json::Value = serde_json::from_str(JSON).expect("re-parse expected");
        assert_eq!(rendered, expected, "request example failed round-trip");
    }
    #[test]
    fn response_example_1() {
        const JSON: &str = "{\n  \"id\": \"urn:uuid:00000000-0000-4000-8000-000000000002\",\n  \"type\": \"https://trusttasks.org/spec/vtc/schemas/list/0.1#response\",\n  \"issuer\": \"did:example:community\",\n  \"recipient\": \"did:example:administrator\",\n  \"issuedAt\": \"2026-09-28T10:00:01Z\",\n  \"threadId\": \"urn:uuid:00000000-0000-4000-8000-0000000001ff\",\n  \"payload\": {\n    \"items\": [\n      {\n        \"typeUri\": \"https://riverside.example/credentials/WorkshopSafety\",\n        \"kind\": \"issues\",\n        \"description\": \"Completed the workshop safety induction.\",\n        \"hasCredentialSchema\": true,\n        \"createdAt\": \"2026-09-28T10:00:01Z\",\n        \"createdByDid\": \"did:example:administrator\"\n      },\n      {\n        \"typeUri\": \"https://openvtc.org/credentials/MembershipCredential\",\n        \"dtgType\": \"MembershipCredential\",\n        \"kind\": \"issues\",\n        \"hasCredentialSchema\": false,\n        \"createdAt\": \"2026-01-01T00:00:00Z\",\n        \"createdByDid\": \"did:example:administrator\"\n      }\n    ]\n  }\n}\n";
        let doc: crate::TrustTask<super::Response> =
            serde_json::from_str(JSON).expect("deserialize response example");
        let rendered = serde_json::to_value(&doc).expect("re-serialize");
        let expected: serde_json::Value = serde_json::from_str(JSON).expect("re-parse expected");
        assert_eq!(rendered, expected, "response example failed round-trip");
    }
    /// Each fixture in `payload.invalid-examples.json` MUST be
    /// rejected by at least one of: serde deserialization, or
    /// JSON-Schema validation under the `validate` feature. The
    /// fixture file documents the producer-side bug class that
    /// each payload exemplifies; this generated test pins it.
    #[cfg(feature = "validate")]
    #[test]
    fn rejects_invalid_examples() {
        use crate::validate::ValidatedPayload;
        let fixtures: &[(&str, &str)] = &[
            ("limit above 100.", "{\n  \"limit\": 500\n}"),
            ("An unknown kind filter.", "{\n  \"kind\": \"all\"\n}"),
        ];
        for (i, (note, raw)) in fixtures.iter().enumerate() {
            let value: serde_json::Value = match serde_json::from_str(raw) {
                Ok(v) => v,
                Err(_) => continue,
            };
            let serde_ok = serde_json::from_value::<super::Payload>(value.clone()).is_ok();
            let schema_ok = super::Payload::validate_value(&value).is_ok();
            assert!(
                !(serde_ok && schema_ok),
                "invalid-example #{} ({:?}) was accepted by both serde and JSON Schema; \
                         the fixture's stated failure class is no longer caught:\n{}",
                i + 1,
                note,
                raw
            );
        }
    }
    /// Each `"variant": "response"` fixture in
    /// `payload.invalid-examples.json` MUST be rejected as a
    /// response payload by at least one of: serde deserialization
    /// into `Response`, or JSON-Schema validation against the
    /// `$anchor: "response"` sub-schema (validate feature).
    #[cfg(feature = "validate")]
    #[test]
    fn rejects_invalid_response_examples() {
        use crate::validate::ValidatedPayload;
        let fixtures: &[(&str, &str)] = &[
            (
                "An item carrying credentialSchema — bodies are show's, and a listing that carried them would be unbounded.",
                "{\n  \"items\": [\n    {\n      \"createdAt\": \"2026-09-28T10:00:01Z\",\n      \"createdByDid\": \"did:example:administrator\",\n      \"credentialSchema\": {},\n      \"hasCredentialSchema\": true,\n      \"kind\": \"issues\",\n      \"typeUri\": \"https://riverside.example/credentials/WorkshopSafety\"\n    }\n  ]\n}",
            ),
            (
                "An item without hasCredentialSchema.",
                "{\n  \"items\": [\n    {\n      \"createdAt\": \"2026-09-28T10:00:01Z\",\n      \"createdByDid\": \"did:example:administrator\",\n      \"kind\": \"issues\",\n      \"typeUri\": \"https://riverside.example/credentials/WorkshopSafety\"\n    }\n  ]\n}",
            ),
        ];
        for (i, (note, raw)) in fixtures.iter().enumerate() {
            let value: serde_json::Value = match serde_json::from_str(raw) {
                Ok(v) => v,
                Err(_) => continue,
            };
            let serde_ok = serde_json::from_value::<super::Response>(value.clone()).is_ok();
            let schema_ok = super::Response::validate_value(&value).is_ok();
            assert!(
                !(serde_ok && schema_ok),
                "invalid response example #{} ({:?}) was accepted by both serde and JSON Schema; \
                         the fixture's stated failure class is no longer caught:\n{}",
                i + 1,
                note,
                raw
            );
        }
    }
}
